WITH ranked AS (SELECT id, session_id, event_time, duration_sec FROM web_events QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY event_time NULLS LAST, id) = 1) SELECT CASE WHEN duration_sec >= 406 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, MIN(event_time) AS first_seen, STDDEV_SAMP(duration_sec) AS duration_sec_stddev_2 FROM ranked GROUP BY CASE WHEN duration_sec >= 406 THEN 'LARGE' ELSE 'SMALL' END ORDER BY duration_sec_tier NULLS LAST
